/**
 * Generates constants/bible-offline.ts from whatever is in assets/bible.
 *
 *   node scripts/build-offline-index.mjs
 *
 * Metro resolves `require` at build time, so every bundled book needs its own
 * literal path — hence a generated file rather than a loop over a directory.
 *
 * Shared by scripts/build-bible.mjs (which produces the KJV) and
 * scripts/import-vpl-bible.mjs (which produces the Creative Commons
 * translations), so adding a translation is a matter of dropping its folder
 * into assets/bible and running this.
 */

import { readdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

export async function writeOfflineIndex() {
  const assetDir = path.join(root, 'assets', 'bible');
  const entries = await readdir(assetDir, { withFileTypes: true });

  // KJV first so it reads as the default it is; the rest alphabetically.
  const translations = entries
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .sort((a, b) => (a === 'kjv' ? -1 : b === 'kjv' ? 1 : a.localeCompare(b)));

  const blocks = [];
  const summary = [];

  for (const translation of translations) {
    const books = (await readdir(path.join(assetDir, translation)))
      .filter((file) => file.endsWith('.json'))
      .map((file) => file.replace(/\.json$/, ''));

    const lines = books
      .map((book) => `    '${book}': () => require('../assets/bible/${translation}/${book}.json'),`)
      .join('\n');

    blocks.push(`  '${translation}': {\n${lines}\n  },`);
    summary.push(`${translation} (${books.length} books)`);
  }

  const file = `// GENERATED by scripts/build-offline-index.mjs — do not edit by hand.
//
// Bible text that ships inside the app: ${summary.join(', ')}.
//
// The KJV is public domain. The Twi editions are Biblica's "Open" editions,
// released under CC BY-SA 4.0 and copied verbatim; the copyright line each
// one requires lives in constants/bible-translations.ts and is shown with the
// text. Bundling them means a reader in Ghana needs no network and no
// account to read scripture in their own language.

type ChapterData = string[][];

export const DEFAULT_TRANSLATION = 'kjv';

const LOADERS: Record<string, Record<string, () => ChapterData>> = {
${blocks.join('\n')}
};

const cache = new Map<string, ChapterData>();

function loadBook(translationId: string, bookId: string): ChapterData | null {
  const key = \`\${translationId}:\${bookId}\`;
  const cached = cache.get(key);
  if (cached) return cached;

  const loader = LOADERS[translationId]?.[bookId];
  if (!loader) return null;

  const data = loader();
  cache.set(key, data);
  return data;
}

/**
 * Verse strings for a chapter, or null when the reference does not exist.
 *
 * Defaults to the KJV, which is also what callers use as the fallback when a
 * remote translation cannot be loaded.
 */
export function getOfflineChapter(
  bookId: string,
  chapter: number,
  translationId: string = DEFAULT_TRANSLATION
): string[] | null {
  const book = loadBook(translationId, bookId);
  if (!book) return null;

  const verses = book[chapter - 1] ?? null;
  // A translation may leave a verse number unused where it merges two verses.
  return verses ? verses.filter((verse) => verse.length > 0) : null;
}

export function hasOfflineBook(
  bookId: string,
  translationId: string = DEFAULT_TRANSLATION
): boolean {
  return Boolean(LOADERS[translationId]?.[bookId]);
}

/** True when the whole translation ships with the app. */
export function isBundledTranslation(translationId: string): boolean {
  return translationId in LOADERS;
}
`;

  await writeFile(path.join(root, 'constants', 'bible-offline.ts'), file, 'utf8');
  return summary;
}

// Only run when invoked directly, so build-bible.mjs can import the function.
if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  writeOfflineIndex()
    .then((summary) => console.log(`Wrote constants/bible-offline.ts — ${summary.join(', ')}`))
    .catch((error) => {
      console.error(error);
      process.exit(1);
    });
}
